Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('49','Pediater','detský lekár, venuje sa starostlivosti o dieťa a to od jeho narodenia až po dosiahnutie dospelosti, lekárska starostlivosť o deti zahrňuje prevenciu, diagnostiku i liečbu ich ochorení');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('50','Plastický chirurg','chirurg zaoberajúci sa chirurgickou nápravou vrodených či získaných tvarových, veľkostných a funkčných odchyliek jednotlivých častí ľudského tela, od normálu');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('51','Pneumológ','lekár, ktorý sa zaoberá výskumom, diagnózou a liečbou pľúcnych ochorení');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('52','Praktický lekár','lekár so všeobecnou praxou (na rozdiel od odborného, špecializovaného), ktorý zaisťuje primárnu liečebnú a preventívnu starostlivosť o dospelú populáciu, môže zaisťovať i starostlivosť o deti a dorast');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('53','Psychiater','lekár, ktorý sa zaoberá rozpoznávaním, prevenciou a liečbou duševných porúch');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('54','Psychológ','"vysokoškolsky študovaný človek, ktorý sa zaoberá ""dušou"""');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('55','Radiológ','lekár zaoberajúci sa rádiodiagnostikou (diagnostikou pomocou röntgenových metód), zaoberajúci sa i ďalšími zobrazovacími metódami, ako sú vyšetrenia ultrazvukom alebo pomocou magnetickej rezonancie, príp. denzitometriou');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('56','Rádioterapeut','lekár zaoberajúci sa rádioterapiou - ožarovaním');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('57','Rehabilitačný lekár','zaoberá sa obnovením pôvodného stavu a schopností pacienta (jeho pohyblivosťou, výkonnosťou, pracovnou schopnosťou)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('58','Reumatológ','lekár zaoberajúci sa výskumom, diagnózou a liečbou zápalových i nezápalových reumatických ochorení kĺbov, šliach, svalov a príbuzných štruktúr');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('59','Sexuológ','lekár zaoberajúci sa ľudskou sexualitou, štúdiom, diagnostikou a liečbou sexuálnych porúch');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('60','Stomatológ','zubný lekár alebo stomatológ sa zaoberá funkciou zubov, kostí a mäkkých tkanív v ústnej dutine.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('61','Toxikológ','lekár, odborný pracovník zaoberajúci sa toxikológiou. Náukou o jedoch a liekoch.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('62','Traumatológ','chirurg zaoberajúci sa komplexnou liečbou poranení, najmä pohybového ústrojenstva ( úrazové lekárstvo )');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('63','Urológ','lekár – chirurg – zaoberajúci sa ochorením močového systému a mužských pohlavných orgánov a ich liečbou, včetne operačnej liečby');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('64','Venerológ','odborník zaoberajúci sa pohlavnými chorobami');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('65','Všeobecný lekár pre deti a dorast','praktický lekár prvého kontaktu, ktorý sa venuje deťom a dorastencom od 0 - 25 rokov');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('66','Všeobecný lekár pre dospelých','iný názov pre praktického lekára, ktorý sa venuje ľuďom starším ako 18, respektíve 25 rokov');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('33','Kardiológ','lekár zaboberajúci sa ochorením srdca a ciev, celkovo sa vyčleňuje s odboru vnútorného alebo interného lekárstva. Oblasť zahŕňa diagnostiku vrodených srdcových chýb, ischemické choroby, srdcové zlyhania a ostatné ochorenia srdca a ciev.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('34','Klinický a dopravný psychológ','Zaoberá sa dopravnou psychológiou. Testuje vodičov.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('35','Klinický biochemik','je lekár v odbore klinická biochémia, ktorý sa zaoberá biochemickými poruchami a analýzami telesných tekutín, buniek a tkanív ako aj interpretáciou získaných výsledkov v zdraví a chorobe.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('36','Logopéd','zaoberá sa prevenciou a nápravou porúch reči u detí i dospelých.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('37','Mamológ','mamológia je medicínsky odbor, ktorý sa zaoberá problematikou ochorení prsníkov. Ide o multidisciplinárny odbor, pretože v sebe zahŕňa diagnostiku, chirurgiu, patológiu a liečbu ochorení mliečnej žľazy.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('38','Mikrobiológ','odborník, ktorý skúma jednobunkové mikroorganizmy, nebunkové organizmy a subvírové patogény');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('39','Nefrológ','lekár zaoberajúci sa výskumom, diagnózou a liečbou chorôb obličiek, vrátane hemo – dialýzy.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('40','Neonatológ','lekár venujúci sa problematike novorodeneckého obdobia, lekár, ktorý spadá do podoboru pediatrie,');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('41','Neurochirurg','chirurg, ktorý sa zaoberá operačnou liečbou ochorení nervového systému, medzi ktoré patria nádory či úrazy mozgu a miechy, periférnych ne');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('42','Neurológ','lekár zaoberajúca sa štúdiom, diagnostikou a neoperačnou liečbou chorôb nervového systému (mozgu, miechy, nervov a nimi inervovaných svalov)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('43','Nozológ','odborník, ktorý sa zaoberá triedením chorôb a systematickým opisom chorôb');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('44','Oftalmológ','očný lekár, zaoberá sa výskumom, diagnózou, prevenciou a liečbou očných chorôb vzhľadom k skutečnosti, že oční lekári prevádzajú operácie očí, sú považovaný za lekárov a chirurgov.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('45','Onkológ','lekár zaoberajúci sa výskumom, diagnózou a liečbou nádorových ochorení (rakoviny), vrátane rádioterapie (liečba žiarením)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('46','Ortopéd',' lekár zaoberajúci sa prevenciou, zisťovaním a liečením vrodených alebo získaných chýb, chorôb a úrazov pohybového ústroja');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('47','Otorinolaryngológ','lekár zaoberajúci sa výskumom, diagnózou, prevenciou a liečbou chorôb : ušných, nosných a krčných. Pracovisko kde pôsobí otorinolaringológ sa bežne označuje ORL');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('48','Patológ','lekár zaoberajúci sa náukou o chorobách (o chorobných pochodoch a zmenách v ľudskom tele)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('1','Akupunkturista','lekár zaoberajúci sa akupuktúrou. Akupunktúra je medicínska metóda pochádzajúca z Číny.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('2','Alergológ a imunológ','lekár zaoberajúcim sa štúdiom, diagnostikou, liečbou a prevenciou chorôb, ktoré sú vyvolávané poruchami imunity (napr. alergia, imunodeficitné stavy a pod.)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('3','Algeziológ','lekár, ktorý sa zaoberá liečením akútnej, chronickej a nádorovej bolesti');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('4','Anestéziológ','lekár zaoberajúci sa anestéziou (znecitlivením), starajúci sa o správne uspatie pacienta pri operácií');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('5','Angiochirurg','cievny chirurg');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('6','Angiológ','lekár z oboru vnútorného lekárstva, tj. internista, zaoberajúci sa štúdiom, diagnostikou, liečbou a prevenciou ochorení ciev');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('7','Audiológ','lekár zaoberajúci sa sluchom a jeho poruchami, lekársky odbor spojený s ORL, odbor lekárstva zaoberajúci sa sluchom a poruchami sluchu');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('8','Chirurg','lekár zaoberajúci sa operačnou liečbou ochorení rôznych orgánov vrátane poranení(napr. kardiochirurg, plastický chirurg a pod.)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('9','Cytológ','odborník v oblasti cytológie');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('10','Dermatológ - kožný lekár','kožný lekár, zaoberá sa výskumom, diagnózou a liečbou kožných chorôb');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('11','Dermatovenerológ','odborný lekár zaoberajúci sa, diagnostikou a liečbou kožných a pohlavných chorôb');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('12','Diabetológ','lekár zaoberajúci sa výskumom, diagnózou, prevenciou a liečbou cukrovky (odborne: diabetes mellitus) a jej komplikáciami');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('13','Diagnostik','lekár, ktorý určuje choroby (diagnózy). Tento odbor sa môže zlučovať s ďalšími.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('14','Endokrinológ','lekár zaoberajúci sa štúdiom žliaz s vnútornou sekréciou a ich produktov (hormónov), diagnostikuje a lieči ich poruchy');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('15','Epidemiológ','lekár, odborník, ktorý študuje v populácií výskyt a rozloženie určitých ochorení, či znakov a javov so vzťahom k zdraviu, medzi ne patria choroby infekčného alebo chronické(napr. srdcové cievne)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('16','Foniatrik','lekár zaoberajúci sa foniatriou. Foniatria (z gréckého slova phoniatria) je lekárskym odborom, ktorý se zaoberá vyšetrovaním funkcií: hlasu, reči a sluchu,');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('17','Ftizeológ','lekár zaoberajúci sa prevenciou, diagnostikou a liečbou tuberkulózy');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('18','Fyzioterapeut','fyzioterapeut pomáha rehabilitovať ľudí, ktorí sa zotavujú po zraneniach, operáciách, alebo ktorí trpia ochoreniami svalstva alebo kĺbov.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('19','Gastroenterológ','lekár zaoberajúci sa výskumom, diagnózou a liečbou chorôb tráviaceho systému (žalúdka, čriev, slinivky brušnej, dvanástorníka.)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('20','Genetik','lekár zaoberajúci sa náukou o dedičnosti, tj. výskumom, diagnostikou, liečbou a prevenciou dedičných porúch a chorôb.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('21','Geriater','lekár, ktorý sa zaoberá prevenciou, diagnostikou, liečbou a rehabilitáciou seniorov, t.j. osôb vo veku nad 65 rokov.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('22','Gerontológ','je lekár, ktorý sa zaoberá procesom starnutia a ochorení týkajúcich sa starnutia.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('23','Gynekológ - Reprodukčná medicína','Reprodukčná medicína je lekársky odbor, ktorý sa zaoberá fyziológiou a odchýlkami reprodukčného systému človeka, so zameraním na liečbu porúch a ochorení reprodukčného systému ženy.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('24','Gynekológ a pôrodník','lekár zaoberajúci sa výskumom, diagnózou, liečbou a prevenciou chorôb ženských pohlavných orgánov, jeho náplňou je tiež starostlivosť o ženu v období tehotenstva, v priebehu pôrodu i po ňom');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('25','Hematológ','lekár, ktorý študuje krv');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('26','Hepatológ',' lekár zaoberajúci sa štúdiom, diagnózou a liečením pečeňových ochorení');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('27','Histológ','lekár, ktorý sa zaoberá štúdiom mikroskopickej štruktúry orgánov a tkanív. Histológia najčastejšie používa svetelný mikroskop a rôzne farbiace techniky.');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('28','Homeopat','lekár, ktorý si svoje lekárske vzdelanie doplnil štúdiom homeopatie');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('29','Hygienik','lekár zaoberajúci sa náukou o zdravom spôsobe života jedinca i spoločnosti, opatreniami, ktoré zabezpečujú ochranu zdravia, ďalej dodržovaním hygienických zásad, noriem a predpisov');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('30','Infektológ','lekár zaoberajúci sa diagnostikou, liečením a výskumom infekčných ochorení');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('31','Internista','lekár zaoberajúci sa diagnózou a nechirurgickou liečbou chorôb vnútorných orgánov (srdca, pľúc, tráviaceho ústrojenstva, žliaz s vnútornou sekréciou atď.)');
Insert into SYSTEM.TYP_LEKARA (ID_TYP,NAZOV,POPIS) values ('32','Kardiochirurg','chirurg, ktorý sa venuje operačnej liečbe ochorení srdca, medzi ktoré patrí vrodené alebo získané vady chlopní, aortokoronárny bypass, transplantácia srdca a iné.');
